/**
 * RS1 power and pricing (GST-1154): eval/runner/rs1/power.ts and pricing.ts and their committed JSON. pricing.json
 * regenerates byte for byte; power's analytic block regenerates, and a small seeded simulation regenerates and is
 * pinned (the committed 1,000-simulation block takes a minute and is regenerated by hand: bun eval/runner/rs1/power.ts).
 * Gate A's line, its refusal (RS1_GATE_A_FAIL, exit 3) and the stage 0 edit point are checked at the boundaries.
 */
import { afterAll, describe, expect, test } from 'bun:test';
import { existsSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { countNames } from '../../eval/runner/name-guard.ts';
import { analyticBlock, FULL_SIMULATION, POWER_FILES, POWER_SCHEMA, powerReport, powerText, RS1_DIR, simulateCheck, type Family } from '../../eval/runner/rs1/power.ts';
import { ASSUMPTIONS, gateA, main, options, price, PRICING_PATH, PRICING_SCHEMA, pricingText, PROGRAM_CAP_USD, STAGE0_INPUTS, STAGE_CAP_USD } from '../../eval/runner/rs1/pricing.ts';

const roots: string[] = [];
const scratch = () => { const d = mkdtempSync(join(tmpdir(), 'rs1-pricing-')); roots.push(d); return d; };
afterAll(() => { for (const d of roots) rmSync(d, { recursive: true, force: true }); });
const KINDS = ['gbrain-defaults', 'ext-extract-first', 'ext-memory-bank', 'ext-temporal-graph', 'baseline-hybrid'];

describe('pricing.ts', () => {
  test('pricing.json regenerates byte for byte', () => {
    expect(pricingText()).toBe(readFileSync(PRICING_PATH, 'utf8'));
    expect(JSON.parse(readFileSync(PRICING_PATH, 'utf8')).schema).toBe(PRICING_SCHEMA);
  });

  test("the draft's inputs reproduce the draft's totals, and gate A passes at N", () => {
    expect(STAGE0_INPUTS).toEqual({ mint_usd_per_conversation: 20, conversation_pass_rate: 1, item_regeneration_rate: 0, mtok_per_conversation: 1.07 });
    const n = price('N', true);
    expect(n.total_estimate).toBe(5772.42);
    expect(price('N', false).total_estimate).toBe(4994.83);
    expect(price('O', true).total_estimate).toBe(14926.46);
    expect(price('O', false).total_estimate).toBe(12852.9);
    expect(n.ingest_by_system).toEqual({ 'gbrain-defaults': 224.1, 'ext-extract-first': 222.45, 'ext-memory-bank': 139.41, 'ext-temporal-graph': 331.55, 'baseline-hybrid': 18.99 });
    expect(n.gate_a).toEqual({ program_cap_usd: 7000, line_usd: 6363.64, pass: true, headroom_usd: 591.22 });
  });

  test('mint at $29 and pass rate 1.0 fails gate A at N: $6,514.92 against $6,363.64', () => {
    const [full, noThink, full90, noThink90] = options();
    expect(full).toMatchObject({ mint_usd_per_conversation: 29, conversation_pass_rate: 1, with_gbrain_think: true, total_estimate: 6514.92, gate_a: { line_usd: 6363.64, pass: false, headroom_usd: -151.28 } });
    expect(noThink).toMatchObject({ conversation_pass_rate: 1, with_gbrain_think: false, total_estimate: 5737.33, gate_a: { pass: true } });
    expect(full90).toMatchObject({ conversation_pass_rate: 0.9, with_gbrain_think: true, total_estimate: 6780.76, gate_a: { pass: false } });
    expect(noThink90).toMatchObject({ conversation_pass_rate: 0.9, with_gbrain_think: false, total_estimate: 6003.17, gate_a: { pass: true } });
    expect(price('N', true, { ...STAGE0_INPUTS, mint_usd_per_conversation: 29 }).total_estimate).toBe(6514.92);
  });

  test("gate A's line is cap / 1.1, inclusive", () => {
    expect(gateA(7000 / 1.1, 7000).pass).toBe(true);
    expect(gateA(6363.64, 7000).pass).toBe(false);
    expect(gateA(6363.63, 7000)).toEqual({ program_cap_usd: 7000, line_usd: 6363.64, pass: true, headroom_usd: 0.01 });
    expect(gateA(0, PROGRAM_CAP_USD.O).line_usd).toBe(16363.64);
  });

  test('the caps are the approved fixed figures, never derived from the estimate', () => {
    const text = pricingText({ ...STAGE0_INPUTS, mint_usd_per_conversation: 200 });
    expect(text).not.toContain('hard_cap');
    const p = JSON.parse(text);
    expect(p.program_cap_usd).toEqual({ N: 7000, O: 18000 });
    expect(p.N_without_think.gate_a.program_cap_usd).toBe(7000);
    expect(p.O_without_think.gate_a.program_cap_usd).toBe(18000);
    for (const v of [p.N, p.O]) { expect(v.stages[0].est).toBe(STAGE_CAP_USD.stage0); expect(v.stages[1].est).toBe(STAGE_CAP_USD.stage1); }
  });

  test('the stage 0 block is the only edit point, and each input moves only its lines', () => {
    for (const k of Object.keys(STAGE0_INPUTS)) expect(Object.keys(ASSUMPTIONS)).not.toContain(k);
    const base = price('N', true);
    const line = (p: ReturnType<typeof price>, what: string) => p.stages.find(s => s.what.startsWith(what))!.est;
    const moved = (p: ReturnType<typeof price>) => p.stages.filter((s, i) => s.est !== base.stages[i].est).map(s => s.what.split(',')[0].split(':')[0]);
    const pass = price('N', true, { ...STAGE0_INPUTS, conversation_pass_rate: 0.9 });
    expect(moved(pass)).toEqual(['Mint and validate in custody', 'Regeneration reserve']);
    expect(line(pass, 'Mint and validate')).toBe(1666.67);
    expect(line(pass, 'Regeneration reserve')).toBe(166.67);
    const regen = price('N', true, { ...STAGE0_INPUTS, item_regeneration_rate: 0.2 });
    expect(line(regen, 'Mint and validate')).toBe(1800);
    expect(line(regen, 'Regeneration reserve')).toBe(180);
    const longer = price('N', true, { ...STAGE0_INPUTS, mtok_per_conversation: 1.07 * 1.15 });
    expect(moved(longer)).toEqual(['Ingest', 'Ingest']);
    expect(Object.keys(longer.ingest_by_system)).toEqual(KINDS);
  });

  test('a failed gate A writes pricing.json first, then exits 3 with RS1_GATE_A_FAIL', () => {
    const out = join(scratch(), 'pricing.json');
    const logs: string[] = [], errors: string[] = [];
    const code = main(['--out', out], { ...STAGE0_INPUTS, mint_usd_per_conversation: 29 }, { log: s => logs.push(s), error: s => errors.push(s) });
    expect(code).toBe(3);
    expect(existsSync(out)).toBe(true);
    expect(JSON.parse(readFileSync(out, 'utf8')).N.total_estimate).toBe(6514.92);
    const err = errors.join('\n');
    expect(err).toContain('[RS1_GATE_A_FAIL]');
    expect(err).toContain('"projected_total_usd":6514.92,"gate_line_usd":6363.64,"shortfall_usd":151.28');
    expect(err).toContain("bring the projection to GBEV-3; a higher cap or a dropped row is Garry's");
    expect(logs.some(l => l.startsWith('gate A FAIL: N projected $6,514.92 against $6,363.64'))).toBe(true);
    const passing = main(['--out', join(scratch(), 'pricing.json')], STAGE0_INPUTS, { log: s => logs.push(s), error: s => errors.push(s) });
    expect(passing).toBe(0);
    expect(logs).toContain('gate A pass: N projected $5,772.42 against $6,363.64 (cap $7,000.00 / 1.1); headroom $591.22');
  });

  test('kind ids, never product names', () => {
    expect(countNames(readFileSync(PRICING_PATH, 'utf8')) + countNames(readFileSync(join(RS1_DIR, 'pricing.ts'), 'utf8'))).toBe(0);
  });
});

describe('power.ts', () => {
  const committed = (f: Family) => readFileSync(join(RS1_DIR, POWER_FILES[f]), 'utf8');

  test('the analytic block regenerates, and the committed file is the script output at 1,000 simulations of 999 draws', () => {
    for (const f of ['servers', 'whole'] as Family[]) {
      const c = JSON.parse(committed(f));
      expect(c.schema).toBe(POWER_SCHEMA);
      const { analytic, needed } = analyticBlock(f);
      expect(c.analytic).toEqual(analytic);
      expect(c.needed).toEqual(needed);
      expect(c.command).toBe(`bun eval/runner/rs1/power.ts --family ${f} --sims 1000 --draws 999`);
      for (const s of c.simulation_checks) expect([s.sims, s.draws]).toEqual([FULL_SIMULATION.sims, FULL_SIMULATION.draws]);
      const rest = { ...powerReport(f, { sims: 1, draws: 9 }), command: c.command, simulation_checks: c.simulation_checks };
      expect(JSON.stringify(rest, null, 1) + '\n').toBe(committed(f));
    }
  });

  test('the headline detectable differences', () => {
    const row = (f: Family, scenario: string, n: number) => JSON.parse(committed(f)).analytic.find((a: any) => a.scenario === scenario && a.questions_per_conversation === 20 && a.tau_points === 2.28).rows.find((r: any) => r.n === n);
    expect(row('servers', 'central', 75).mdd80).toBe(2.94);
    expect(row('servers', 'optimistic', 75).mdd80).toBe(2.61);
    expect(row('servers', 'pessimistic', 75).mdd80).toBe(3.48);
    expect(row('servers', 'central', 200).mdd80).toBe(1.78);
    expect(row('whole', 'file-agent', 75).mdd80).toBe(3.47);
    expect(row('servers', 'central', 75).level_margin80).toBe(3.34);
  });

  test('a small seeded simulation regenerates byte for byte, with both rules reported', () => {
    const small = { sims: 40, draws: 199 };
    expect(powerText('whole', small)).toBe(powerText('whole', small));
    expect(simulateCheck('servers', 'central', 75, 20, small)).toEqual({ n: 75, q: 20, scenario: 'central', analytic_mdd80: 2.94, sims: 40, draws: 199,
      bonferroni: { simulated_power_at_mdd: 0.825, simulated_fwer_at_zero: 0.1 }, holm: { simulated_power_at_mdd: 0.825, simulated_fwer_at_zero: 0.1 } });
    expect(simulateCheck('whole', 'file-agent', 75, 20, small)).toEqual({ n: 75, q: 20, scenario: 'file-agent', analytic_mdd80: 3.47, sims: 40, draws: 199,
      bonferroni: { simulated_power_at_mdd: 0.95, simulated_fwer_at_zero: 0.05 }, holm: { simulated_power_at_mdd: 0.95, simulated_fwer_at_zero: 0.05 } });
  });

  test('F25: the decisive Bonferroni rule beside Holm in the committed simulation', () => {
    const servers = JSON.parse(committed('servers')), whole = JSON.parse(committed('whole'));
    expect(servers.decisive_rule).toBe('Bonferroni: 3 x p <= 0.05 (the 98.33% interval excludes 0)');
    for (const c of servers.simulation_checks) {
      expect(c.holm.simulated_power_at_mdd).toBeGreaterThanOrEqual(c.bonferroni.simulated_power_at_mdd);
      expect(c.holm.simulated_fwer_at_zero).toBe(c.bonferroni.simulated_fwer_at_zero);
    }
    for (const c of whole.simulation_checks) expect(c.holm).toEqual(c.bonferroni);
    const central75 = servers.simulation_checks.find((c: any) => c.scenario === 'central' && c.n === 75);
    expect([central75.bonferroni.simulated_power_at_mdd, central75.holm.simulated_power_at_mdd, central75.bonferroni.simulated_fwer_at_zero]).toEqual([0.775, 0.777, 0.058]);
    expect(servers.comparators).toEqual(['ext-extract-first', 'ext-memory-bank', 'ext-temporal-graph']);
    expect(countNames(committed('servers')) + countNames(committed('whole')) + countNames(readFileSync(join(RS1_DIR, 'power.ts'), 'utf8'))).toBe(0);
  });
});
